public static class TokenCache
{
    public static async Task<string?> GetAuthPayloadAsync(
        IDatabase redis,
        string sessionId,
        CancellationToken cancellationToken)
    {
        var value = await redis.StringGetAsync(sessionId)
            .ConfigureAwait(false);
        cancellationToken.ThrowIfCancellationRequested();
        return value.IsNullOrEmpty ? null : value.ToString();
    }
}

// WinForms button click handler on UI thread:
private void LoadData_Click(object sender, EventArgs e)
{
    // DEADLOCK: UI thread blocked in Result,
    // continuation needs UI thread to finish
    var data = LoadDataAsync().Result;
    label.Text = data;
}

private async Task<string> LoadDataAsync()
{
    var response = await httpClient.GetStringAsync(url);
    // continuation tries to post back to UI thread
    return response;
}

public async Task ProcessRequestAsync(HttpContext context)
{
    var userId = context.User.FindFirst("sub")?.Value; // capture first

    var data = await FetchDataAsync(userId!)
        .ConfigureAwait(false);

    // context may not be valid on this thread — use captured userId
    await SaveAsync(userId!, data);
}

// Thread 1 (UI thread) — BLOCKED:
//   at System.Threading.Tasks.Task.InternalWaitCore(...)
//   at System.Threading.Tasks.Task.Wait()
//   at System.Threading.Tasks.Task`1.get_Result()
//   at MyForm.btnLoad_Click(...)          <-- sync-over-async entry
//   at System.Windows.Forms.Control.OnClick(...)

// Thread 1 continuation — QUEUED but cannot run:
//   at System.Threading.SynchronizationContext.Send(...)
//   at System.Threading.Tasks.SynchronizationContextAwaitTaskContinuation.Run(...)
//   at MyForm.LoadDataAsync(...)          <-- needs UI thread

